<script setup lang="ts">import{onMounted,ref}from'vue';import http from'../api/http';const rows=ref<any[]>([]);async function load(){const{data}=await http.get('/plm/ecns',{params:{page:1,size:50}});rows.value=data.data.content}async function submit(r:any){await http.post(`/plm/ecns/${r.id}/submit`);load()}async function implement(r:any){await http.post(`/plm/ecns/${r.id}/implement`);load()}onMounted(load)</script><template><el-card><template #header>工程变更单（ECN）</template><el-alert title="变更单审批通过后才可实施；实施后应创建新的 BOM 版本并走 BOM 审批。" type="warning" :closable="false"/><el-table :data="rows" style="margin-top:16px"><el-table-column prop="ecnNo" label="ECN 编号"/><el-table-column prop="ecnTitle" label="主题"/><el-table-column prop="bomCode" label="涉及 BOM"/><el-table-column prop="changeType" label="类型"/><el-table-column prop="status" label="状态"><template #default="{row}">{{$zh(row.status)}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='DRAFT'" size="small" @click="submit(row)">提交评审</el-button><el-button v-if="row.status==='APPROVED'" type="success" size="small" @click="implement(row)">确认实施</el-button></template></el-table-column></el-table></el-card></template>
